from vllm.v1.cudagraph_dispatcher import CudagraphDispatcher


class NPUGraphDispatcher(CudagraphDispatcher):

    def _create_padded_batch_descriptor(
        self, num_tokens: int, uniform_decode: bool, has_lora: bool
    ) -> BatchDescriptor:
        max_num_seqs = self.vllm_config.scheduler_config.max_num_seqs
        uniform_decode_query_len = self.uniform_decode_query_len
        num_tokens_padded = self.vllm_config.pad_for_cudagraph(num_tokens)

        if (uniform_decode 
            and self.cudagraph_mode.has_mode(CUDAGraphMode.FULL)
            and num_tokens_padded % uniform_decode_query_len == 0
        ):
            num_reqs = num_tokens_padded // uniform_decode_query_len
            assert num_tokens_padded % uniform_decode_query_len == 0
        else:
            uniform_decode = False
            num_reqs = min(num_tokens_padded, max_num_seqs)

        return BatchDescriptor(
            num_tokens=num_tokens_padded,
            num_reqs=num_reqs,
            uniform=uniform_decode,
            has_lora=has_lora,
        )

    def _relax_batch_descriptor_for_mixed_batch_cudagraphs(self, batch_descriptor):
        max_num_seqs = self.vllm_config.scheduler_config.max_num_seqs

        return BatchDescriptor(
            batch_descriptor.num_tokens,
            num_reqs=min(max_num_seqs, batch_descriptor.num_tokens),
            uniform=False,
            has_lora=batch_descriptor.has_lora
        )


    def initialize_cudagraph_keys(
        self, cudagraph_mode: CUDAGraphMode, uniform_decode_query_len: int
    ):
        # This should be called only after attention backend is initialized. So we can
        # get the correct cudagraph mode after backend support is resolved.
        self.cudagraph_mode = cudagraph_mode

        # LoRA activation cases to specialize the cuda graphs on
        if self.vllm_config.lora_config:
            if self.compilation_config.cudagraph_specialize_lora:
                lora_cases = [True, False]
            else:
                lora_cases = [True]
        else:
            lora_cases = [False]

        # Note: we create all valid keys for cudagraph here but do not
        # guarantee all keys would be used. For example, if we allow lazy
        # capturing in future PR, some keys may never be triggered.
        if cudagraph_mode.mixed_mode() != CUDAGraphMode.NONE:
            for bs, has_lora in product(
                self.compilation_config.cudagraph_capture_sizes, lora_cases
            ):
                # Adapt start
                self.add_cudagraph_key(
                    cudagraph_mode.mixed_mode(),
                    self._relax_batch_descriptor_for_mixed_batch_cudagraphs(
                        self._create_padded_batch_descriptor(
                        bs, False, has_lora
                    )),
                )
                # Adapt end

        # if decode cudagraph mode is FULL, and we don't already have mixed
        # mode full cudagraphs then add them here.
        if (
            cudagraph_mode.decode_mode() == CUDAGraphMode.FULL
            and cudagraph_mode.separate_routine()
        ):
            max_num_tokens = (
                uniform_decode_query_len
                * self.vllm_config.scheduler_config.max_num_seqs
            )
            cudagraph_capture_sizes_for_decode = [
                x
                for x in self.compilation_config.cudagraph_capture_sizes
                if x <= max_num_tokens and x >= uniform_decode_query_len
            ]
            for bs, has_lora in product(cudagraph_capture_sizes_for_decode, lora_cases):
                self.add_cudagraph_key(
                    CUDAGraphMode.FULL,
                    self._create_padded_batch_descriptor(bs, True, has_lora),
                )

        self.keys_initialized = True

    def dispatch(
        self,
        num_tokens: int,
        uniform_decode: bool,
        has_lora: bool,
        disable_full: bool = False,
    ) -> tuple[CUDAGraphMode, BatchDescriptor]:
        """
        Given conditions(e.g.,batch descriptor and if using cascade attention),
        dispatch to a cudagraph runtime mode and the valid batch descriptor.
        A new batch descriptor is returned as we might dispatch a uniform batch
        to a graph that supports a more general batch (uniform to non-uniform).
        """
        if (
            not self.keys_initialized
            or self.cudagraph_mode == CUDAGraphMode.NONE
            or num_tokens > self.compilation_config.max_cudagraph_capture_size
        ):
            return CUDAGraphMode.NONE, BatchDescriptor(num_tokens)

        batch_desc = self._create_padded_batch_descriptor(
            num_tokens, uniform_decode, has_lora
        )
        # Adapt start
        relaxed_batch_desc = self._relax_batch_descriptor_for_mixed_batch_cudagraphs(batch_desc)
        # Adapt end
        if not disable_full:
            # check if key exists for full cudagraph
            if batch_desc in self.cudagraph_keys[CUDAGraphMode.FULL]:
                return CUDAGraphMode.FULL, batch_desc

            # otherwise, check if the relaxed key exists
            if relaxed_batch_desc in self.cudagraph_keys[CUDAGraphMode.FULL]:
                return CUDAGraphMode.FULL, relaxed_batch_desc

        # also check if the relaxed key exists for more "general"
        # piecewise cudagraph
        if relaxed_batch_desc in self.cudagraph_keys[CUDAGraphMode.PIECEWISE]:
            return CUDAGraphMode.PIECEWISE, relaxed_batch_desc

        # finally, just return no cudagraphs and a trivial batch descriptor
        return CUDAGraphMode.NONE, BatchDescriptor(num_tokens)

class ConfigUpdater:
    """Handles configuration validation and updates for the NPU platform."""

    @classmethod
    def update_vllm_config(cls, vllm_config: 'VllmConfig') -> None:
        """Update the vLLM configuration for NPU compatibility.

        Args:
            vllm_config: The vLLM configuration to update.
        """
        from omni_npu.compilation.ge_compile_config import NPUCompilationConfig
        vllm_config.npu_compilation_config = NPUCompilationConfig()
        import os
        vllm_config.npu_compilation_config.use_gegraph = os.getenv("TORCH_COMPILE_GE", "False").lower() == "true"
        cls._handle_graph_mode(vllm_config)

        additional_config = vllm_config.additional_config
        if additional_config:
            graph_model_compile_config = additional_config.get("graph_model_compile_config", None)
            if graph_model_compile_config is not None:
                vllm_config.npu_compilation_config.build_from_cli(graph_model_compile_config, vllm_config)
                logger.debug(f"Graph model compile config: {graph_model_compile_config}")

    @staticmethod
    def _handle_graph_mode(vllm_config: 'VllmConfig') -> None:
        """Handle graph mode configuration for NPU."""
        from vllm.utils.torch_utils import supports_dynamo
        if not supports_dynamo():
            logger.warning("Graph mode unsupported due to low torch version. Disabling.")
            vllm_config.npu_compilation_config.use_gegraph = False


class NPUPlatform(Platform):
    try:
        # In case vllm already defined HUAWEI_NPU platform
        _enum = PlatformEnum.HUAWEI_NPU
    except AttributeError:
        # fallback to OOT
        _enum = PlatformEnum.OOT
    device_name: str = "npu"
    device_type: str = "npu"
    dispatch_key: str = "PrivateUse1"
    ray_device_key: str = "NPU"
    dist_backend: str = "hccl"
    device_control_env_var: str = "ASCEND_RT_VISIBLE_DEVICES"

    def __init__(self):
        """Initialize the NPU platform and configure environment."""
        super().__init__()

    @classmethod
    def set_device(cls, device: torch.device) -> None:
        torch.npu.set_device(device)

    @classmethod
    def get_device_name(cls, device_id: int = 0) -> str:
        return torch.npu.get_device_name(device_id)

    @classmethod
    def inference_mode(cls):
        return torch.no_grad()

    @classmethod
    def import_kernels(cls):
        from omni_npu.compilation.decorators import patch_compile_decorators
        patch_compile_decorators()

        from omni_npu.connector import register_connectors
        register_connectors()

        for ep in entry_points().select(group="omni.kv_connectors"):
            try:
                register_fn = ep.load()
                register_fn()
            except Exception as e:
                logger.warning(f"Failed to load connector {ep.name}: {e}")

    @classmethod
    def get_current_memory_usage(cls, device: Optional[torch.types.Device] = None) -> float:
        torch.npu.reset_peak_memory_stats(device)
        return torch.npu.max_memory_allocated(device)

    @classmethod
    def device_count(cls) -> int:
        return torch.npu.device_count()

    @classmethod
    def mem_get_info(cls) -> tuple[int, int]:
        return torch.npu.mem_get_info()

    def is_cuda_alike(self) -> bool:
        """Stateless version of [torch.cuda.is_available][]."""
        scope = traceback.format_stack()[-2]
        caller = traceback.extract_stack(limit=2)[0]
        caller_file = caller.filename.replace("\\", "/")
        is_npu = getattr(self, "device_type", None) == "npu"
        if is_npu:
            if "parallel.py" in scope and "is_cuda_alike" in scope:
                return True
            if (
                caller.name == "bind_kv_cache"
                and caller_file.endswith("vllm/v1/worker/utils.py")
            ):
                return True
        return self._enum in (PlatformEnum.CUDA, PlatformEnum.ROCM)

    @classmethod
    def pre_register_and_update(
        cls, parser: Optional["FlexibleArgumentParser"] = None
    ) -> None:
        """
        Do some pre-registration or update action for the current platform.

        This function is called before global VllmConfig is initialized or cli
        arguments are parsed. It's used for out-of-tree platforms to register or
        update the configuration.

        For example, the out-of-tree quantization config can be imported and
        registered here dynamically.
        """
        # Import NPU custom layers to ensure they're registered before use
        from omni_npu import layers

    @classmethod
    def check_and_update_config(cls, vllm_config: "VllmConfig") -> None:  # type: ignore[name-defined]
        ConfigUpdater.update_vllm_config(vllm_config)
        # Minimal defaults to match vLLM expectations.
        parallel_config = vllm_config.parallel_config
        parallel_config.worker_cls = "omni_npu.worker.npu_worker.NPUWorker"

        cache_config = vllm_config.cache_config
        if cache_config and cache_config.block_size is None:
            cache_config.block_size = 128

        vllm_config.compilation_config.pass_config.fuse_norm_quant = False
        vllm_config.compilation_config.pass_config.fuse_act_quant = False
        vllm_config.compilation_config.pass_config.fuse_attn_quant = False

        from vllm.config.compilation import CUDAGraphMode

        if (vllm_config.compilation_config.cudagraph_mode == CUDAGraphMode.FULL_DECODE_ONLY or
           vllm_config.compilation_config.cudagraph_mode == CUDAGraphMode.FULL):
            logger.info("using only ACL Graph Mode")
            vllm_config.compilation_config.splitting_ops = []

    @classmethod
    def get_punica_wrapper(cls) -> str:
        # Use CPU punica wrapper by default
        return "vllm.lora.punica_wrapper.punica_cpu.PunicaWrapperCPU"

    @classmethod
    def get_device_communicator_cls(cls) -> str:
        # Point vLLM to our HCCL-based communicator implementation
        return "omni_npu.distributed.communicator.NPUCommunicator"

    @classmethod
    def get_attn_backend_cls(
        cls,
        selected_backend,
        attn_selector_config,
    ) -> str:
        # Import here to avoid circular import and ensure plugins are loaded
        from omni_npu.attention.backends.utils import get_attention_backend
        if attn_selector_config.use_mla:
            if attn_selector_config.use_sparse:
                backend_name = "NPUDSA"
            else:
                backend_name = "NPUMLA"
        else:
            backend_name = "VLLM_NPU_ATTN"

        # Query registry first (allows plugins to override)
        registered_path = get_attention_backend(backend_name)
        return registered_path

    @property
    def simple_compile_backend(self):
        return "eager"

    @classmethod
    def support_static_graph_mode(cls) -> bool:
        """
        Returns if the graph mode is supported by the current platform.
        """
        return True

    @classmethod
    def get_static_graph_wrapper_cls(cls) -> str:
        """
        Get piecewise backend class for piecewise graph.
        """
        return "omni_npu.compilation.acl_graph.ACLGraphWrapper"

    @classmethod
    def get_pass_manager_cls(cls) -> str:
        """
        Get the pass manager class for the current platform.
        """
        return "omni_npu.compilation.pass_manager.GraphPassManager"

    @classmethod
    def get_compile_backend(cls) -> str:
        """
        Get the custom compile backend for current platform.
        """
        return "omni_npu.compilation.npugraph_ex.NpuGraphExAdaptor"

    @classmethod
    def support_hybrid_kv_cache(cls) -> bool:
        return True

    def is_sleep_mode_available(self) -> bool:
        """
        Returns if the sleep mode is available for the current platform.
        """

    model._omni_npu_load_weights_hooked = True

def _model_post_weight_load(self, model: nn.Module | None) -> None:
    if model is None:
        return
    post_weight_load = getattr(model, "post_weight_load", None)
    if callable(post_weight_load):
        post_weight_load()

def model_post_weight_load(self) -> None:
    if self.model_config.enable_sleep_mode:
        allocator = NpuMemAllocator.get_instance()
        context = allocator.use_memory_pool(tag="weights")
    else:
        context = nullcontext()
    with context, set_current_vllm_config(self.vllm_config):
        self._model_post_weight_load(self.get_model())
        self._model_post_weight_load(self.get_drafter_model())

def load_model(self, eep_scale_up: bool = False) -> None:
    """
    Args:
        eep_scale_up: the model loading is for elastic EP scale up.
    """
    logger.debug(f"<<< {self.vllm_config.npu_compilation_config.use_gegraph=}")
    if self.vllm_config.npu_compilation_config.use_gegraph:
        from vllm.model_executor.model_loader import get_model as original_get_model
        self.model = original_get_model(vllm_config=self.vllm_config)
        return
    super().load_model(eep_scale_up)

    if hasattr(self.model, "model"):
        prefetch_post_load_hook = getattr(self.model.model, "prefetch_post_load", None)
        if callable(prefetch_post_load_hook):
            prefetch_post_load_hook()

    if hasattr(self, "drafter") and isinstance(self.drafter, EagleProposer):
        prepare_communication_buffer_for_model(self.drafter.model)

    # wrap the model with full graph wrapper if needed.
    logger.debug(f"<<< {self.compilation_config.cudagraph_mode.has_full_cudagraphs()=}")
    if self.compilation_config.cudagraph_mode.has_full_cudagraphs():
        set_graph_params(self.compilation_config.cudagraph_capture_sizes)
        self.update_stream: torch.npu.Stream = torch.npu.Stream()

        attn_layer_names = set(get_layers_from_vllm_config(self.vllm_config, AttentionLayerBase).keys())
        if hasattr(self, "drafter") and isinstance(self.drafter, EagleProposer):
            attn_layer_names = attn_layer_names - set(self.drafter.attn_layer_names)
        attn_layer_names = list(attn_layer_names)

        self.model = ACLGraphWrapper(self.model.runnable,
                                     self.vllm_config,
                                     runtime_mode=CUDAGraphMode.FULL,
                                     update_stream=self.update_stream,
                                     attn_layer_names=attn_layer_names,
                                    )
        logger.debug("<<< Wrapped original model with ACLGraphWrapper")
        if hasattr(self, "drafter") and isinstance(self.drafter, EagleProposer):
            n_predict = getattr(self.drafter, "n_predict", 1)
            if n_predict == 1:
                self.draft_update_stream: torch.npu.Stream = torch.npu.Stream()
                self.drafter.model = ACLGraphWrapper(
                    self.drafter.model,
                    self.vllm_config,
                    runtime_mode=CUDAGraphMode.FULL,
                    update_stream=self.draft_update_stream,
                    attn_layer_names=self.drafter.attn_layer_names,
                )
                logger.debug("<<< Wrapped drafter model with ACLGraphWrapper")
            else:
                mtp_start_layer_idx = self.drafter.model.config.num_hidden_layers
                self.draft_update_stream: torch.npu.Stream = torch.npu.Stream()

                wrapped_layers = dict()
                for i in range(n_predict):
                    mtp_layer_i = mtp_start_layer_idx + i
                    mtp_layer_i_attn_names = [
                        item for item in self.drafter.attn_layer_names
                        if self.drafter.model.get_spec_layer(item) == mtp_layer_i
                    ]
                    wrapped_layers[str(mtp_layer_i)] = ACLGraphWrapper(
                        self.drafter.model.model.layers[str(mtp_layer_i)],
                        self.vllm_config,
                        runtime_mode=CUDAGraphMode.FULL,
                        update_stream=self.draft_update_stream,
                        attn_layer_names=mtp_layer_i_attn_names,
                    )
                self.drafter.model.model.wrapped_layers = wrapped_layers
                logger.debug("<<< Wrapped multi mtp layers of drafter model with ACLGraphWrapper")
    self._is_mm_encoder_only = supports_mm_encoder_only(self.model)
    self._hook_model_load_weights(self.get_model())
    self._hook_model_load_weights(self.get_drafter_model())

def _get_eagle3_aux_layers_from_config(self) -> tuple[int, ...] | None:
    if not (self.speculative_config and self.speculative_config.draft_model_config):
        return None

    hf_config = self.speculative_config.draft_model_config.hf_config

    layer_ids = getattr(hf_config, "eagle_aux_hidden_state_layer_ids", None)
    if layer_ids and isinstance(layer_ids, (list, tuple)):
        return tuple(layer_ids)

    eagle_config = getattr(hf_config, "eagle_config", None)
    if not isinstance(eagle_config, dict):
        return None

    layer_ids = eagle_config.get("eagle_aux_hidden_state_layer_ids")
    if layer_ids and isinstance(layer_ids, (list, tuple)):
        return tuple(layer_ids)

    return None

def reset_input_batch(self) -> None:
    self.input_batch.block_table.clear()
    for block_table in self.input_batch.block_table.block_tables:
        block_table.slot_mapping.gpu.fill_(0)
        block_table.slot_mapping.cpu.fill_(0)

